              "text": "\"\"\"Inventory: unit parsing and formatting for stock quantities.\"\"\"\n\nimport re\nfrom decimal import Decimal, ROUND_HALF_UP\n\n_UNIT_FACTORS = {\n    \"g\": Decimal(1),\n    \"kg\": Decimal(1000),\n}\n\n_QTY_RE = re.compile(r\"\\s*(\\d+(?:\\.\\d+)?)\\s*(g|kg)\\s*\", re.IGNORECASE)\n\n\ndef parse_qty(text):\n    \"\"\"Inventory: Parse a quantity string into a whole number of grams.\n\n    Accepts a non-negative number followed by the unit \"g\" or \"kg\"\n    (case-insensitive, with optional surrounding whitespace). The result is\n    the quantity in whole grams, rounded to the nearest gram with halves\n    rounded up.\n\n    Args:\n        text: Quantity string, e.g. \"3kg\", \"250 g\" or \"1.5 kg\".\n\n    Returns:\n        int: The quantity expressed in whole grams.\n\n    Raises:\n        ValueError: If text is not a string containing a valid quantity.\n    \"\"\"\n    if not isinstance(text, str):\n        raise ValueError(f\"Quantity must be a string, got {type(text).__name__}\")\n    match = _QTY_RE.fullmatch(text)\n    if match is None:\n        raise ValueError(f\"Invalid quantity: {text!r}\")\n    value = Decimal(match.group(1)) * _UNIT_FACTORS[match.group(2).lower()]\n    return int(value.quantize(Decimal(1), rounding=ROUND_HALF_UP))\n"
