    names, tested = set(), False
    for m in msgs:
        if m["role"] == "assistant":
            names |= {b["name"] for b in m["content"] if b.get("type") == "toolCall"}
        if m["role"] == "toolResult" and re.search(r"\d+ (passed|failed)", blocks_text(m["content"])):
